DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def cell(g, r, k):
    """Off-board reads as a wall: the rim counts as an occupied neighbour."""
    return g[r][k] if 0 <= r < len(g) and 0 <= k < len(g[0]) else '#'


def step(g, r, k):
    return sum(cell(g, r + i, k + j) != '.' for i, j in DIRS)


def legal(g, ch):
    H = len(g); W = len(g[0]); out = []
    for r in range(H):
        for k in range(W):
            if g[r][k] != ch:
                continue
            n = step(g, r, k)
            if not n:
                continue
            for i, j in DIRS:
                a, b = r + n * i, k + n * j
                if 0 <= a < H and 0 <= b < W and g[a][b] == '.':
                    out.append((r, k, a, b))
    return out


def play(g, m):
    r, k, a, b = m
    h = [row[:] for row in g]
    h[a][b] = h[r][k]; h[r][k] = '.'
    return h


def settled(rr, H, W, no, nx, nw):
    """A random position in which no 'x' has a legal move (walls added to repair)."""
    g = [['.'] * W for _ in range(H)]
    cells = [(r, c) for r in range(H) for c in range(W)]
    rr.shuffle(cells)
    it = iter(cells)
    for ch, cnt in (('x', nx), ('o', no), ('#', nw)):
        for _ in range(cnt):
            r, c = next(it); g[r][c] = ch
    for _ in range(8):
        M = legal(g, 'x')
        if not M:
            return g
        r, k, a, b = rr.choice(M)
        g[a][b] = '#'
    return None


def decorrelated(G, M, m):
    """Reject positions where a cheap heuristic would pick the winner for free."""
    H = len(G); W = len(G[0])
    X = [(r, c) for r in range(H) for c in range(W) if G[r][c] == 'x']
    ln = lambda q: abs(q[0] - q[2]) + abs(q[1] - q[3])
    dx = lambda r, c: min(abs(r - a) + abs(c - b) for a, b in X)
    if len([q for q in M if ln(q) >= ln(m)]) < 2:
        return False
    if len([q for q in M if dx(q[2], q[3]) <= dx(m[2], m[3])]) < 2:
        return False
    if dx(m[2], m[3]) == 1 and len([q for q in M if dx(q[2], q[3]) == 1]) < 2:
        return False
    B = [q for q in M if any(cell(G, q[0] + i, q[1] + j) == 'x' for i, j in DIRS)]
    if m in B and len(B) < 2:
        return False
    return True


def generate(seed):
    rr = random.Random(seed)
    H, W = rr.choice([(6, 6), (6, 6), (6, 6), (5, 6), (6, 5), (5, 5)])
    for _ in range(400):
        F = settled(rr, H, W, rr.randint(3, 4), rr.randint(2, 4), rr.randint(1, 3))
        if not F:
            continue
        cand = []
        for d in range(H):
            for e in range(W):
                if F[d][e] != 'o':
                    continue
                for i, j in DIRS:
                    for n in range(1, 6):
                        a, b = d - n * i, e - n * j
                        if not (0 <= a < H and 0 <= b < W) or F[a][b] != '.':
                            continue
                        G = [row[:] for row in F]
                        G[a][b] = 'o'; G[d][e] = '.'
                        if step(G, a, b) == n:
                            cand.append(G)
        rr.shuffle(cand)
        for G in cand:
            M = legal(G, 'o')
            if len(M) < 8 or not legal(G, 'x'):
                continue
            Wn = [q for q in M if not legal(play(G, q), 'x')]
            if len(Wn) != 1 or not decorrelated(G, M, Wn[0]):
                continue
            return "\n".join("".join(row) for row in G)
    return "\n".join("".join(row) for row in F)

